(()=>{const side=document.getElementById('workspace-sidebar'),brand=document.querySelector('.global-header .brand'),user=document.querySelector('.global-header .user');brand.setAttribute('role','button');brand.setAttribute('aria-label','返回首页，选择角色');brand.setAttribute('title','返回首页');brand.tabIndex=0;brand.style.cursor='pointer';brand.onclick=()=>showRoleSelection();brand.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();showRoleSelection()}};const top=document.createElement('div');top.className='sidebar-brand';top.append(brand);side.prepend(top);top.append(document.getElementById("sidebar-collapse"));document.querySelector(".sidebar-heading").hidden=true;const bottom=document.createElement('div');bottom.className='sidebar-profile';bottom.append(user);side.append(bottom);const settings=document.getElementById('settings-nav');settings.setAttribute('aria-label','设置');settings.title='设置';settings.innerHTML='<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="m9 3-.7 2.2-2 .9L4 5.7 2 9l1.6 1.8v2.4L2 15l2 3.3 2.3-.4 2 .9L9 21h4l.7-2.2 2-.9 2.3.4 2-3.3-1.6-1.8v-2.4L20 9l-2-3.3-2.3.4-2-.9L13 3Z"/><circle cx="11" cy="12" r="3"/></svg>';user.append(settings);document.querySelector('.sidebar-settings').hidden=true})();
